initJs:
function(container, apiUrl, tables) {
  let currentRecordId = null;
  let originalData = null;

  // DOM要素の取得
  const selectWorkRecord = container.querySelector("#select-work-record");
  const inputWorkDate = container.querySelector("#input-work-date");
  const inputStartTime = container.querySelector("#input-start-time");
  const inputEndTime = container.querySelector("#input-end-time");
  const inputTotalTime = container.querySelector("#input-total-time");
  const inputBreakTime = container.querySelector("#input-break-time");
  const inputNetTime = container.querySelector("#input-net-time");
  const selectWorkItem = container.querySelector("#select-work-item");
  const inputCorrectionReason = container.querySelector("#input-correction-reason");
  const textareaWorkDetail = container.querySelector("#textarea-work-detail");
  const warningArea = container.querySelector("#warning-area");
  const warningMessage = container.querySelector("#warning-message");
  const btnSave = container.querySelector("#btn-save");
  const btnCancel = container.querySelector("#btn-cancel");
  const btnShowOriginal = container.querySelector("#btn-show-original");
  const originalDataModal = container.querySelector("#original-data-modal");
  const btnCloseModal = container.querySelector("#btn-close-modal");
  const originalDataContent = container.querySelector("#original-data-content");

  // 作業記録一覧の読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録テーブル
    if (records) {
      selectWorkRecord.innerHTML = '<option value="">選択してください</option>';
      records.forEach(record => {
        const option = document.createElement('option');
        option.value = record.id;
        option.textContent = `${record.作業日 || ''} - ${record.プロジェクト名 || ''} (${record.作業種別 || ''})`;
        selectWorkRecord.appendChild(option);
      });
    }
  }

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタテーブル
    if (items) {
      selectWorkItem.innerHTML = '<option value="">選択してください</option>';
      items.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
        selectWorkItem.appendChild(option);
      });
    }
  }

  // 時間計算
  function calculateTime() {
    const startTime = inputStartTime.value;
    const endTime = inputEndTime.value;
    const breakTime = parseInt(inputBreakTime.value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01 ${startTime}`);
      const end = new Date(`2000-01-01 ${endTime}`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        const hours = Math.floor(totalMinutes / 60);
        const minutes = totalMinutes % 60;
        inputTotalTime.value = `${hours}時間${minutes}分`;

        const netMinutes = totalMinutes - breakTime;
        if (netMinutes >= 0) {
          const netHours = Math.floor(netMinutes / 60);
          const netMins = netMinutes % 60;
          inputNetTime.value = `${netHours}時間${netMins}分`;

          // 異常値チェック
          checkAbnormalValues(totalMinutes, breakTime);
        } else {
          inputNetTime.value = '';
          showWarning('中断時間が作業時間を超えています');
        }
      } else {
        inputTotalTime.value = '';
        inputNetTime.value = '';
      }
    } else {
      inputTotalTime.value = '';
      inputNetTime.value = '';
    }
  }

  // 異常値チェック
  function checkAbnormalValues(totalMinutes, breakTime) {
    const warnings = [];

    if (totalMinutes > 12 * 60) { // 12時間超
      warnings.push('作業時間が12時間を超えています');
    }

    if (breakTime > totalMinutes * 0.5) { // 中断時間が作業時間の50%超
      warnings.push('中断時間が作業時間の50%を超えています');
    }

    if (totalMinutes < 30) { // 30分未満
      warnings.push('作業時間が30分未満です');
    }

    if (warnings.length > 0) {
      showWarning(warnings.join('、'));
    } else {
      hideWarning();
    }
  }

  // 警告表示
  function showWarning(message) {
    warningMessage.textContent = message;
    warningArea.classList.remove('hidden');
  }

  // 警告非表示
  function hideWarning() {
    warningArea.classList.add('hidden');
  }

  // 作業記録選択時の処理
  selectWorkRecord.addEventListener('change', async function() {
    const recordId = this.value;
    if (recordId) {
      const records = await window.aivicApi.list(1);
      const record = records?.find(r => r.id === recordId);
      if (record) {
        currentRecordId = recordId;
        originalData = record;

        // フォームに既存データを設定
        inputWorkDate.value = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';

        if (record.作業開始時刻) {
          const startTime = new Date(record.作業開始時刻);
          inputStartTime.value = startTime.toTimeString().slice(0, 5);
        }

        if (record.作業終了時刻) {
          const endTime = new Date(record.作業終了時刻);
          inputEndTime.value = endTime.toTimeString().slice(0, 5);
        }

        textareaWorkDetail.value = record.作業内容 || '';

        // 中断時間の取得
        const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
        const totalBreakTime = breakRecords?.filter(br => br.作業記録ID === recordId)
          .reduce((sum, br) => sum + (br.中断時間 || 0), 0) || 0;
        inputBreakTime.value = totalBreakTime;

        calculateTime();
      }
    } else {
      currentRecordId = null;
      originalData = null;
      // フォームをクリア
      inputWorkDate.value = '';
      inputStartTime.value = '';
      inputEndTime.value = '';
      inputTotalTime.value = '';
      inputBreakTime.value = '';
      inputNetTime.value = '';
      textareaWorkDetail.value = '';
      inputCorrectionReason.value = '';
      hideWarning();
    }
  });

  // 時間入力時の計算
  inputStartTime.addEventListener('change', calculateTime);
  inputEndTime.addEventListener('change', calculateTime);
  inputBreakTime.addEventListener('input', calculateTime);

  // 元データ参照ボタン
  btnShowOriginal.addEventListener('click', function() {
    if (originalData) {
      const content = `
        <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px; margin-bottom: 8px;">
          <strong>作業日:</strong><span>${originalData.作業日 ? new Date(originalData.作業日).toLocaleDateString('ja-JP') : ''}</span>
          <strong>開始時刻:</strong><span>${originalData.作業開始時刻 ? new Date(originalData.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</span>
          <strong>終了時刻:</strong><span>${originalData.作業終了時刻 ? new Date(originalData.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</span>
          <strong>作業時間:</strong><span>${originalData.作業時間 ? Math.floor(originalData.作業時間/60) + '時間' + (originalData.作業時間%60) + '分' : ''}</span>
          <strong>プロジェクト:</strong><span>${originalData.プロジェクト名 || ''}</span>
          <strong>作業場所:</strong><span>${originalData.作業場所 || ''}</span>
          <strong>作業種別:</strong><span>${originalData.作業種別 || ''}</span>
          <strong>作業内容:</strong><span>${originalData.作業内容 || ''}</span>
          <strong>進捗状況:</strong><span>${originalData.進捗状況 || ''}</span>
          <strong>承認状態:</strong><span>${originalData.承認状態 || ''}</span>
        </div>
      `;
      originalDataContent.innerHTML = content;
      originalDataModal.classList.remove('hidden');
    }
  });

  // モーダル閉じる
  btnCloseModal.addEventListener('click', function() {
    originalDataModal.classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  originalDataModal.addEventListener('click', function(e) {
    if (e.target === originalDataModal) {
      originalDataModal.classList.add('hidden');
    }
  });

  // キャンセルボタン
  btnCancel.addEventListener('click', function() {
    if (confirm('修正内容を破棄しますか？')) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 修正完了ボタン
  btnSave.addEventListener('click', async function() {
    if (!currentRecordId) {
      alert('修正対象の作業記録を選択してください');
      return;
    }

    if (!inputCorrectionReason.value.trim()) {
      alert('修正理由を入力してください');
      return;
    }

    if (!inputStartTime.value || !inputEndTime.value) {
      alert('作業開始時刻と終了時刻を入力してください');
      return;
    }

    const startDateTime = new Date(`${inputWorkDate.value} ${inputStartTime.value}`);
    const endDateTime = new Date(`${inputWorkDate.value} ${inputEndTime.value}`);
    const workTimeMinutes = (endDateTime - startDateTime) / (1000 * 60);

    const updateData = {
      作業開始時刻: startDateTime.toISOString(),
      作業終了時刻: endDateTime.toISOString(),
      作業時間: workTimeMinutes,
      作業内容: textareaWorkDetail.value.trim(),
      更新日時: new Date().toISOString()
    };

    const result = await window.aivicApi.update(1, currentRecordId, updateData);
    if (result) {
      // 異常値ログの記録
      if (!warningArea.classList.contains('hidden')) {
        const logData = {
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentRecordId,
          ユーザーID: 'current-user', // 実際の実装では現在のユーザーIDを使用
          異常値種別: '修正データ異常値',
          検出項目: '作業時間',
          検出値: `${Math.floor(workTimeMinutes/60)}時間${workTimeMinutes%60}分`,
          閾値: '標準範囲外',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };
        await window.aivicApi.save(4, logData); // 異常値検出ログテーブル
      }

      alert('工数データを修正しました');
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み
  loadWorkRecords();
  loadWorkItems();
}
